@Override
    public void render(T entity, float yaw, float tickDelta, MatrixStack matrices,
                       VertexConsumerProvider vertexConsumers, int light) {
        float progress = entity.getLifeProgress(tickDelta);
        int count = Math.max(1, entity.getGlyphCount());
        Vec3d target = resolveTargetOffset(entity, tickDelta);

        Vec3d direction = target.lengthSquared() < 1.0E-4 ? UP : target.normalize();
        Vec3d perp1 = direction.crossProduct(UP);
        if (perp1.lengthSquared() < 1.0E-4) {
            perp1 = direction.crossProduct(new Vec3d(1.0, 0.0, 0.0));
        }
        perp1 = perp1.normalize();
        Vec3d perp2 = direction.crossProduct(perp1).normalize();

        float age = entity.age + tickDelta;
        int seed = entity.getSeed();
        float stagger = count > 1 ? (1.0F - FLIGHT_SPAN) / (count - 1) : 0.0F;

        for (int i = 0; i < count; i++) {
            float t = MathHelper.clamp((progress - i * stagger) / FLIGHT_SPAN, 0.0F, 1.0F);
            if (t <= 0.0F || t >= 1.0F) {
                continue;
            }
            float alpha = MathHelper.clamp(Math.min(t / 0.12F, (1.0F - t) / 0.22F), 0.0F, 1.0F) * 0.95F;
            if (alpha <= 0.01F) {
                continue;
            }

            long glyphSeed = seed + i * 6871L;
            float phase = (float) BoltPath.unit(glyphSeed, 0L, 1L) * MathHelper.TAU;
            float swing = (0.35F + (float) BoltPath.unit(glyphSeed, 0L, 2L) * 0.35F)
                    * MathHelper.sin(t * MathHelper.PI);
            float ease = t * t * (3.0F - 2.0F * t);

            Vec3d lateral = perp1.multiply(MathHelper.cos(phase) * swing)
                    .add(perp2.multiply(MathHelper.sin(phase) * swing));
            Vec3d pos = target.multiply(ease).add(lateral).add(0.0, (1.0F - ease) * 0.35F, 0.0);
            int glyphIndex = (int) (BoltPath.unit(glyphSeed, 0L, 3L) * 64.0);

            matrices.push();
            matrices.translate(pos.x, pos.y, pos.z);
            matrices.multiply(this.dispatcher.getRotation());
            matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(
                    MathHelper.sin(age * 0.14F + i * 1.9F) * 14.0F));
            ParchmentRendering.renderGlyph(matrices, vertexConsumers, entity.getGlyphStyleId(), glyphIndex,
                    0.26F * (1.0F - ease * 0.35F), alpha);
            matrices.pop();
        }

        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

private void renderBlessing(T entity, float age, float tickDelta,
                                MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        Vec3d anchor = resolveAnchorOffset(entity, tickDelta);
        float sealHeight = entity.getOrbitHeight();
        float bob = MathHelper.sin(age * 0.08F) * 0.05F;

        matrices.push();
        matrices.translate(anchor.x, anchor.y + sealHeight + bob, anchor.z);
        matrices.push();
        matrices.multiply(this.dispatcher.getRotation());
        float pulse = 1.0F + MathHelper.sin(age * 0.11F) * 0.05F;
        ParchmentRendering.renderSeal(matrices, vertexConsumers, light, 0.34F * pulse, 1.0F);
        matrices.pop();

        if (!shouldHideRibbons(entity)) {
            for (int r = 0; r < 2; r++) {
                float side = r == 0 ? 1.0F : -1.0F;
                float sway = MathHelper.sin(age * 0.07F + r * 2.4F) * 0.16F;
                float swayZ = MathHelper.cos(age * 0.055F + r * 1.7F) * 0.12F;
                List<Vec3d> path = new ArrayList<>();
                int samples = 10;
                float length = sealHeight * 0.72F;
                for (int i = 0; i <= samples; i++) {
                    float t = i / (float) samples;
                    path.add(new Vec3d(
                            side * (0.08 + t * t * 0.12) + sway * t,
                            -0.12 - t * length,
                            swayZ * t + MathHelper.sin(age * 0.13F + t * 5.0F + r) * 0.045F * t));
                }
                ParchmentRendering.renderRibbon(matrices, vertexConsumers, light, path, 0.085F,
                        new Vec3d(MathHelper.cos(age * 0.03F + r), 0.0, MathHelper.sin(age * 0.03F + r)).normalize(),
                        age, 0.95F);
            }
        }
        matrices.pop();

        int pages = Math.min(entity.getPageCount(), 3);
        float radius = entity.getOrbitRadius();
        for (int i = 0; i < pages; i++) {
            float phase = i * (MathHelper.TAU / Math.max(1, pages));
            float angle = phase + age * 0.03F;
            double x = anchor.x + MathHelper.cos(angle) * radius;
            double z = anchor.z + MathHelper.sin(angle) * (radius * 0.8F);
            double y = anchor.y + sealHeight * 0.45F + MathHelper.sin(age * 0.09F + phase) * 0.14F;
            matrices.push();
            matrices.translate(x, y, z);
            matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-angle * MathHelper.DEGREES_PER_RADIAN + 90.0F));
            matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(MathHelper.sin(age * 0.06F + i * 2.0F) * 18.0F));
            ParchmentRendering.renderBentPage(matrices, vertexConsumers, light,
                    age, i * 3.1F, 0.26F, 0.3F, 0.5F, 0.9F);
            matrices.pop();
        }
    }

public static void renderRibbon(MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light,
                                    List<Vec3d> path, float halfWidth, Vec3d widthDir,
                                    float age, float alpha) {
        int count = path.size();
        if (count < 2) {
            return;
        }

        Matrix4f matrix = matrices.peek().getPositionMatrix();
        VertexConsumer vertices = vertexConsumers.getBuffer(RenderLayer.getEntityTranslucent(RIBBON_TEXTURE));
        int packedLight = floorLight(light);
        int a = (int) (MathHelper.clamp(alpha, 0.0F, 1.0F) * 255.0F);

        Vec3d[] sides = new Vec3d[count];
        float[] lengths = new float[count];
        float total = 0.0F;
        for (int i = 0; i < count; i++) {
            Vec3d tangent = path.get(Math.min(i + 1, count - 1)).subtract(path.get(Math.max(i - 1, 0)));
            Vec3d side;
            if (widthDir != null) {
                side = widthDir;
            } else {
                side = tangent.crossProduct(new Vec3d(0.0, 1.0, 0.0));
                if (side.lengthSquared() < 1.0E-4) {
                    side = tangent.crossProduct(new Vec3d(1.0, 0.0, 0.0));
                }
            }
            float taper = Math.min(1.0F, Math.min(i, count - 1 - i) / 2.5F + 0.25F);
            sides[i] = side.normalize().multiply(halfWidth * taper);
            if (i > 0) {
                total += (float) path.get(i).distanceTo(path.get(i - 1));
            }
            lengths[i] = total;
        }

        float tileLength = Math.max(0.25F, halfWidth * 2.0F * RIBBON_TILE_ASPECT);
        float scroll = age * 0.012F;
        for (int i = 0; i < count - 1; i++) {
            float v0 = lengths[i] / tileLength + scroll;
            float v1 = lengths[i + 1] / tileLength + scroll;
            Vec3d p0a = path.get(i).add(sides[i]);
            Vec3d p0b = path.get(i).subtract(sides[i]);
            Vec3d p1a = path.get(i + 1).add(sides[i + 1]);
            Vec3d p1b = path.get(i + 1).subtract(sides[i + 1]);
            vertex(vertices, matrix, p0a, 0.0F, v0, 255, a, packedLight);
            vertex(vertices, matrix, p0b, 1.0F, v0, 255, a, packedLight);
            vertex(vertices, matrix, p1b, 1.0F, v1, 255, a, packedLight);
            vertex(vertices, matrix, p1a, 0.0F, v1, 255, a, packedLight);
        }
    }

public static List<Vec3d> buildWindingPath(Vec3d start, Vec3d end, long seed, float age,
                                               float amplitude, int samples) {
        Random random = new Random(seed);
        float phase1 = random.nextFloat() * MathHelper.TAU;
        float phase2 = random.nextFloat() * MathHelper.TAU;
        float waves1 = 1.5F + random.nextFloat() * 1.5F;
        float waves2 = 2.0F + random.nextFloat() * 1.5F;

        Vec3d axis = end.subtract(start);
        Vec3d perp1 = axis.crossProduct(new Vec3d(0.0, 1.0, 0.0));
        if (perp1.lengthSquared() < 1.0E-4) {
            perp1 = axis.crossProduct(new Vec3d(1.0, 0.0, 0.0));
        }
        perp1 = perp1.normalize();
        Vec3d perp2 = axis.crossProduct(perp1).normalize();

        List<Vec3d> path = new ArrayList<>(samples + 1);
        for (int i = 0; i <= samples; i++) {
            float t = i / (float) samples;
            float envelope = MathHelper.sin(t * MathHelper.PI);
            float o1 = MathHelper.sin(t * MathHelper.TAU * waves1 + phase1 + age * 0.055F) * amplitude * envelope;
            float o2 = MathHelper.sin(t * MathHelper.TAU * waves2 + phase2 + age * 0.038F) * amplitude * 0.6F * envelope;
            path.add(start.add(axis.multiply(t)).add(perp1.multiply(o1)).add(perp2.multiply(o2)));
        }
        return path;
    }

public static void renderGlyph(MatrixStack matrices, VertexConsumerProvider vertexConsumers,
                                   Identifier styleId, int glyphIndex, float scale, float alpha) {
        ParchmentGlyphStyle style = ParchmentVisualRegistry.getGlyphStyle(styleId);
        int cell = Math.floorMod(glyphIndex, style.columns() * style.rows());
        float u0 = (cell % style.columns()) / (float) style.columns();
        float v0 = (cell / style.columns()) / (float) style.rows();
        float u1 = u0 + 1.0F / style.columns();
        float v1 = v0 + 1.0F / style.rows();

        renderTexturedQuad(matrices, vertexConsumers,
                RenderLayer.getEntityTranslucentEmissive(style.glowTexture()), FULLBRIGHT,
                scale * style.haloScale(), u0, v0, u1, v1,
                alpha * style.haloAlpha(), style.glowColor());
        renderTexturedQuad(matrices, vertexConsumers,
                RenderLayer.getEntityTranslucentEmissive(style.glyphTexture()), FULLBRIGHT,
                scale, u0, v0, u1, v1, alpha, style.glyphColor());
    }

public static void renderGlyphArc(MatrixStack matrices, VertexConsumerProvider vertexConsumers,
                                      Identifier styleId, int glyphBase, int glyphCount,
                                      float progress, float age, float scale) {
        int count = Math.max(1, glyphCount);
        float written = progress * count;
        for (int i = 0; i < count; i++) {
            float reveal = MathHelper.clamp(written - i, 0.0F, 1.0F);
            if (reveal <= 0.0F) {
                continue;
            }
            float arc = (i / (float) Math.max(1, count - 1) - 0.5F) * 1.75F;
            float jitterX = MathHelper.sin(age * 0.23F + i * 3.7F) * 0.02F;
            float jitterY = MathHelper.sin(age * 0.19F + i * 2.3F) * 0.02F;

            matrices.push();
            matrices.translate(
                    (MathHelper.sin(arc) * 0.55F + jitterX) * scale,
                    (0.12F + MathHelper.cos(arc) * 0.08F + jitterY + (1.0F - reveal) * 0.08F) * scale,
                    (-MathHelper.cos(arc) * 0.5F - 0.15F) * scale);
            matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180.0F - arc * 24.0F));
            matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(
                    MathHelper.sin(age * 0.11F + i * 1.9F) * 9.0F));
            renderGlyph(matrices, vertexConsumers, styleId, glyphBase + i,
                    (0.16F + reveal * 0.04F) * scale, reveal * (0.6F + progress * 0.4F));
            matrices.pop();
        }
    }

private static void drawTrail(DawnquiverRenderPass pass, VertexConsumer vertices, Matrix4f matrix,
                                  Vec3d forward, Vec3d side, Vec3d up,
                                  float scale, float age, int seed) {
        VertexConsumer body = pass.isBody() ? vertices : null;
        VertexConsumer glow = pass.isGlow() ? vertices : null;
        Vec3d[] path = new Vec3d[TRAIL_SPANS + 1];
        for (int span = 0; span <= TRAIL_SPANS; span++) {
            float t = span / (float) TRAIL_SPANS;
            double wave = Math.sin(t * Math.PI * 1.4 + age * 0.16 + seed * 0.01)
                    * t * 0.10 * scale;
            path[span] = forward.multiply(-0.72 * scale - t * 6.8 * scale)
                    .add(side.multiply(wave));
        }

        DawnquiverRenderGeometry.taperedRibbon(glow, matrix, path, side,
                0.48 * scale, 0.008, 255, 156, 28, 210, 0);
        DawnquiverRenderGeometry.taperedRibbon(glow, matrix, path, up,
                0.48 * scale, 0.008, 255, 181, 38, 210, 0);
        DawnquiverRenderGeometry.taperedRibbon(body, matrix, path, side,
                0.15 * scale, 0.002, 255, 241, 190, 230, 0);
        DawnquiverRenderGeometry.taperedRibbon(body, matrix, path, up,
                0.15 * scale, 0.002, 255, 247, 218, 230, 0);

        for (int filament = 0; filament < 3; filament++) {
            Vec3d[] filamentPath = new Vec3d[TRAIL_SPANS + 1];
            double phase = seed * 0.017 + filament * MathHelper.TAU / 3.0;
            for (int span = 0; span <= TRAIL_SPANS; span++) {
                float t = span / (float) TRAIL_SPANS;
                double radius = (0.18 + t * 0.42) * scale;
                double angle = phase + t * MathHelper.TAU * 0.72 + age * 0.08;
                filamentPath[span] = forward.multiply(-0.55 * scale - t * 5.2 * scale)
                        .add(side.multiply(Math.cos(angle) * radius))
                        .add(up.multiply(Math.sin(angle) * radius));
            }
            DawnquiverRenderGeometry.taperedRibbon(glow, matrix, filamentPath,
                    filament % 2 == 0 ? up : side,
                    0.07 * scale, 0.003, 255, 221, 116, 145, 0);
        }
    }

private static ThrowAnimation throwAnimation(float age, int firstThrowTick, int throwInterval,
                                                 int throwCount) {
        if (throwCount <= 0) {
            return new ThrowAnimation(0.0F, 0.0F);
        }
        float releaseTick = firstThrowTick;
        if (throwInterval > 0 && age > firstThrowTick) {
            int cycle = MathHelper.clamp(Math.round((age - firstThrowTick) / throwInterval),
                    0, throwCount - 1);
            releaseTick += cycle * throwInterval;
        }
        float lead = throwInterval > 0
                ? Math.min(5.0F, Math.max(1.0F, throwInterval * 0.55F))
                : 5.0F;
        float recovery = throwInterval > 0
                ? Math.min(4.0F, Math.max(0.75F, throwInterval * 0.4F))
                : 4.0F;
        float relative = age - releaseTick;
        if (relative < -lead || relative > recovery) {
            return new ThrowAnimation(0.0F, 0.0F);
        }
        float acceleration = Math.min(2.0F, lead * 0.45F);
        if (relative < -acceleration) {
            float progress = smooth((relative + lead) / Math.max(0.01F, lead - acceleration));
            return new ThrowAnimation(MathHelper.lerp(progress, 0.0F, -34.0F), progress * 0.45F);
        }
        if (relative < 0.0F) {
            float progress = smooth((relative + acceleration) / Math.max(0.01F, acceleration));
            return new ThrowAnimation(MathHelper.lerp(progress, -34.0F, 94.0F),
                    MathHelper.lerp(progress, 0.45F, 1.0F));
        }
        float progress = smooth(relative / Math.max(0.01F, recovery));
        return new ThrowAnimation(MathHelper.lerp(progress, 94.0F, 0.0F), 1.0F - progress);
    }

@Override
    public void render(DawnquiverBowVisualEntity entity, float yaw, float tickDelta,
                       MatrixStack matrices, VertexConsumerProvider consumers, int light) {
        if (IrisCompat.isRenderingShadowPass()) {
            return;
        }

        float age = entity.age + tickDelta;
        float remaining = entity.getLifetime() - age;
        float opacity = MathHelper.clamp(age / 2.0F, 0.0F, 1.0F)
                * MathHelper.clamp(remaining / FADE_OUT_TICKS, 0.0F, 1.0F);
        if (opacity <= 0.01F) {
            return;
        }

        boolean passive = entity.getMode() == DawnquiverBowVisualEntity.MODE_PASSIVE;
        float formTicks = passive ? 2.4F : FORMATION_TICKS;
        float formation = DawnquiverRenderGeometry.easeOutBack(
                MathHelper.clamp(age / formTicks, 0.0F, 1.0F));
        boolean released = entity.getPhase() == DawnquiverBowVisualEntity.PHASE_RELEASED;
        float releaseDelay = passive ? 2.0F : 0.0F;
        float sinceRelease = released
                ? Math.max(0.0F, age - entity.getReleaseAge() - releaseDelay)
                : 0.0F;
        float snap = released ? DawnquiverRenderGeometry.easeOutCubic(
                MathHelper.clamp(sinceRelease / RELEASE_TICKS, 0.0F, 1.0F)) : 0.0F;
        float draw = passive ? 1.0F : entity.getDrawProgress();

        LivingEntity owner = entity.getOwner();
        boolean firstPerson = entity.getMode() != DawnquiverBowVisualEntity.MODE_FIXED
                && isFirstPersonOwner(owner);
        Vec3d entityOrigin = entity.getLerpedPos(tickDelta);
        Vec3d aimDirection = renderDirection(entity, owner, tickDelta);
        Vec3d displayDirection = firstPerson && owner != null
                ? normalizedOrFallback(owner.getRotationVec(tickDelta), aimDirection)
                : aimDirection;
        Vec3d renderOrigin = renderOrigin(entity, owner, tickDelta, firstPerson, displayDirection);
        float renderYaw = directionYaw(aimDirection);
        float renderPitch = directionPitch(aimDirection);

        float configuredScale = (float) Math.max(0.1, Config.uniqueEffects.dawnquiver.bowScale);
        float baseScale = entity.getScale() * configuredScale;
        float firstPersonScale = firstPerson ? 0.58F : 1.0F;
        float formedScale = MathHelper.lerp(MathHelper.clamp(formation, 0.0F, 1.0F), 0.28F, 1.0F);
        float chargeScale = MathHelper.lerp(draw, 0.92F, 1.12F);
        float releaseScale = MathHelper.lerp(snap, 1.0F, 0.78F);
        float scale = baseScale * firstPersonScale * formedScale * chargeScale * releaseScale;
        float roll = firstPerson ? 0.0F
                : (entity.getHand() == Hand.OFF_HAND ? -1.0F : 1.0F) * 7.0F;

        matrices.push();
        matrices.translate(renderOrigin.x - entityOrigin.x,
                renderOrigin.y - entityOrigin.y,
                renderOrigin.z - entityOrigin.z);
        if (firstPerson) {
            matrices.multiply(this.dispatcher.getRotation());
        } else {
            matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-renderYaw));
            matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(renderPitch));
        }
        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(roll));
        matrices.scale(scale, scale, scale);
        Matrix4f matrix = matrices.peek().getPositionMatrix();

        drawPass(DawnquiverRenderPass.BODY, DawnquiverRenderPass.BODY.getBuffer(consumers), matrix,
                age, draw, formation, snap, opacity, entity.getSeed(), released);
        drawPass(DawnquiverRenderPass.GLOW, DawnquiverRenderPass.GLOW.getBuffer(consumers), matrix,
                age, draw, formation, snap, opacity, entity.getSeed(), released);

        matrices.pop();
        super.render(entity, yaw, tickDelta, matrices, consumers, light);
    }
